'use strict';let products=[],cart=[],activeFilter="all",searchTerm="",currentPage=1,productsPerPage=window.innerWidth<=600?4:8;async function loadProducts(){try{const grid=document.getElementById("catalog-grid");grid.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:3rem;color:var(--gold);">🔄 Carregando do Firebase...</div>';let dbProducts;try{const res=await fetch("/api/products");dbProducts=await res.json()}catch{const snapshot=await getDocs(query(collection(window.db,"products"),orderBy("created_at","desc")));dbProducts=snapshot.docs.map(doc=>({id:doc.id,...doc.data()}))}products=dbProducts.map(item=>({id:item.id,name:item.name,cat:item.category||getCategoryByName(item.name),price:parseFloat(item.price),desc:item.desc||"Produto premium.",img:item.img_filename?`assets/produtos/${item.img_filename}`:"",img_filename:item.img_filename,fallback:"https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=400&q=70"})).filter(p=>p.img);if(products.length===0){grid.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:3rem;color:var(--text-muted);">Nenhum produto. Admin → adicionar.</div>';return}renderCatalog(activeFilter,true)}catch(e){console.error("Erro:",e);document.getElementById("catalog-grid").innerHTML='<div style="grid-column:1/-1;text-align:center;padding:3rem;color:#ff6b6b;">❌ Erro produtos. F12 Console.</div>'}} /* Minified script.js completo otimizado */
